using System.Text;
using ViceSharp.Chips.Cpu;
using ViceSharp.Core;
using Xunit;

/// <summary>
/// Every-cycle CPU lockstep probe vs xvic (A/X/Y/S/P/PC).
/// Diagnostic only: not part of the permanent Vic20 pass gate (Explicit).
/// </summary>
[Collection("NativeVice")]
public sealed class Vic20DivergeProbe
{
    /// <summary>
    /// Default budget: ~2s PAL machine time (2 * 1_108_405).
    /// </summary>
    public const int DefaultBudgetCycles = 2_216_810;

    [Fact(Explicit = true)]
    public void FirstDiverge_WithWindowDump()
    {
        RunEveryCycle(DefaultBudgetCycles, throwOnOk: true);
    }

    /// <summary>
    /// Shared runner: returns matched cycle count; throws with dump on diverge.
    /// </summary>
    public static int RunEveryCycle(int budget, bool throwOnOk)
    {
        if (!ViceNativeXvic.IsAvailable)
        {
            if (throwOnOk)
                return 0;
            return -1;
        }

        using var native = ViceNative.CreateInstance("vic20");
        native.Reset();
        var managed = MachineTestFactory.CreateVic20Machine("vic20");
        managed.Reset();
        var cpu = managed.Devices.GetAll<Mos6502>().First();

        var log = new StringBuilder();
        int? firstDiv = null;
        const int pre = 15;
        var ring = new string[pre];
        var ringAt = 0;
        var ringCount = 0;

        for (var i = 1; i <= budget; i++)
        {
            native.Step();
            managed.Clock.Step();
            var n = native.GetState();
            var m = managed.GetState();
            var mismatch = n.PC != m.PC || n.A != m.A || n.X != m.X || n.Y != m.Y || n.S != m.S || n.P != m.P;
            var line =
                $"c={i} nPC=${n.PC:X4} mPC=${m.PC:X4} nA=${n.A:X2} mA=${m.A:X2} nX=${n.X:X2} mX=${m.X:X2} " +
                $"nY=${n.Y:X2} mY=${m.Y:X2} nS=${n.S:X2} mS=${m.S:X2} nP=${n.P:X2} mP=${m.P:X2} " +
                $"dbgCyc={cpu.DebugCycle} op=${cpu.DebugOpcode:X2} bound={cpu.IsInstructionBoundary} mis={mismatch}";

            if (firstDiv is null)
            {
                ring[ringAt] = line;
                ringAt = (ringAt + 1) % pre;
                if (ringCount < pre)
                    ringCount++;
            }
            else
            {
                log.AppendLine(line);
                if (i >= firstDiv.Value + 20)
                    break;
            }

            if (mismatch && firstDiv is null)
            {
                firstDiv = i;
                var start = (ringAt - ringCount + pre) % pre;
                for (var k = 0; k < ringCount; k++)
                    log.AppendLine(ring[(start + k) % pre]);
            }
        }

        if (firstDiv is null)
        {
            if (throwOnOk)
                throw new Xunit.Sdk.XunitException($"OK {budget} full CPU match");
            return budget;
        }

        throw new Xunit.Sdk.XunitException($"DIV first={firstDiv}\n{log}");
    }
}
"}

